INSERT INTO practice_templates (name, description, groups_json, blocks_json, built_in, created_by) VALUES
  ('Throws M0: Technique school (shot)', 'Week-one teaching day from the program''s Strike School. Grip, placement, and release before any full throws. Phase: intro week.', '["throws"]', '[{"kind": "warmup", "title": "Throws warm-up", "minutes": 15, "groups": ["throws"], "details": "Jog 400m, then: A-skips 3 x 20y, bounds 3 x 15y, broad jumps 3 x 6, speed skaters 3 x 8 each, plyo push-ups 3 x 5, striders 3 x 40y. Every jump and bound is max effort with a full walk back. Class-choice days: the chosen class picks 3 movements x 2 rounds.", "workoutId": null, "attempts": null, "results": []}, {"kind": "drills", "title": "Strike School", "minutes": 30, "groups": ["throws"], "details": "Grip and hold x10, arm and shot placement x10, push and vertical release x10, striking horizontal release x10. Everyone uses a light shot or a 6-8 lb ball; no full throws this week.", "workoutId": null, "attempts": null, "results": []}, {"kind": "workout", "title": "Stand throws", "minutes": 15, "groups": ["throws"], "details": "Stand throws x10 at 80% effort. One cue per athlete.", "workoutId": null, "attempts": null, "results": []}, {"kind": "strength", "title": "Lift A: lower-body power", "minutes": 40, "groups": ["throws"], "details": "1a Power clean + front squat 6 x 2/4. Weeks 1-2 at RPE 7, week 3 at RPE 8; add weight only when every rep is fast. Rest 2:00.\n2a DB Bulgarian split squat 4 x 6 each, 2b BB RDL 4 x 6 (RPE 7-8).\n3a Cossack squat 3 x 6 each, 3b landmine rotational press 3 x 6 each.", "workoutId": null, "attempts": null, "results": []}, {"kind": "cooldown", "title": "Mobility + core", "minutes": 15, "groups": ["throws"], "details": "Mobility: deep squat hold 2 x 1:00, 90/90 hip stretch 2 x 1:00 each, kneeling lunge hold 2 x 1:00 each, seated T-spine rotations 2 x 5 each, tib raises 2 x 25. Core: MB Russian twists 3 x 20, dead bugs 3 x 10, side plank 3 x 0:30 each.", "workoutId": null, "attempts": null, "results": []}]', 0, 'Cloverleaf throws 2026-27'),
  ('Throws M0: Technique school (discus)', 'Week-one teaching day from the program''s Flight School. Grip, swing, and release before turns. Phase: intro week.', '["throws"]', '[{"kind": "warmup", "title": "Throws warm-up", "minutes": 15, "groups": ["throws"], "details": "Jog 400m, then: A-skips 3 x 20y, bounds 3 x 15y, broad jumps 3 x 6, speed skaters 3 x 8 each, plyo push-ups 3 x 5, striders 3 x 40y. Every jump and bound is max effort with a full walk back. Class-choice days: the chosen class picks 3 movements x 2 rounds.", "workoutId": null, "attempts": null, "results": []}, {"kind": "drills", "title": "Flight School", "minutes": 30, "groups": ["throws"], "details": "Grip and hold x10, swing and release (bowling roll) x10, horizontal swing and wind x10, wind and throw x10. Use rings or rubber discs first.", "workoutId": null, "attempts": null, "results": []}, {"kind": "workout", "title": "Stand throws", "minutes": 15, "groups": ["throws"], "details": "Stand throws x10 at 80% effort. One cue per athlete.", "workoutId": null, "attempts": null, "results": []}, {"kind": "strength", "title": "Lift B: upper-body strength", "minutes": 40, "groups": ["throws"], "details": "1a Bench press 5 x 5, building to one top set at RPE 8; 1b bent-over row 5 x 5.\n2a SA DB incline press 4 x 8 each, 2b pull-ups 4 x 6-8.\n3a DB reverse fly 3 x 12, 3b SA DB external rotation 3 x 10 each, farmer''s carry 3 x 30y.", "workoutId": null, "attempts": null, "results": []}, {"kind": "cooldown", "title": "Mobility + core", "minutes": 15, "groups": ["throws"], "details": "Mobility: wall slides 2 x 10, cross-body stretch 2 x 1:00, kneeling thoracic extension 2 x 10 each, cat-cow 2 x 10. Core: plank shoulder taps 3 x 10 each, V-ups 3 x 10, hollow body hold 3 x 0:30.", "workoutId": null, "attempts": null, "results": []}]', 0, 'Cloverleaf throws 2026-27'),
  ('Throws (any phase): Testing day', 'Benchmarks to run in the intro week, at the end of general prep, and mid-competition. Recorded marks show whether training is working, which the past calendars could not.', '["throws"]', '[{"kind": "warmup", "title": "Throws warm-up", "minutes": 15, "groups": ["throws"], "details": "Jog 400m, then: A-skips 3 x 20y, bounds 3 x 15y, broad jumps 3 x 6, speed skaters 3 x 8 each, plyo push-ups 3 x 5, striders 3 x 40y. Every jump and bound is max effort with a full walk back. Class-choice days: the chosen class picks 3 movements x 2 rounds.", "workoutId": null, "attempts": null, "results": []}, {"kind": "measured", "title": "Standing long jump", "minutes": 10, "groups": ["throws"], "details": "Best of 3. Record feet and inches.", "workoutId": null, "attempts": 3, "results": []}, {"kind": "measured", "title": "Overhead back med-ball throw", "minutes": 10, "groups": ["throws"], "details": "Best of 3. Boys 4 kg, girls 3 kg. Measure from the toe line.", "workoutId": null, "attempts": 3, "results": []}, {"kind": "measured", "title": "Shot stand throw", "minutes": 15, "groups": ["throws"], "details": "Best of 3 with the competition implement.", "workoutId": null, "attempts": 3, "results": []}, {"kind": "measured", "title": "Discus stand throw", "minutes": 15, "groups": ["throws"], "details": "Best of 3 with the competition implement.", "workoutId": null, "attempts": 3, "results": []}, {"kind": "cooldown", "title": "Mobility", "minutes": 10, "groups": ["throws"], "details": "Deep squat hold 2 x 1:00, 90/90 hip stretch 2 x 1:00 each, cat-cow 2 x 10.", "workoutId": null, "attempts": null, "results": []}]', 0, 'Cloverleaf throws 2026-27'),
  ('Throws M1: Shot technique + lower power', 'General prep (March). High drill volume with few full throws, plus Lift A. Run weeks 1-2 as written; week 3 is a deload (use the deload template).', '["throws"]', '[{"kind": "warmup", "title": "Throws warm-up", "minutes": 15, "groups": ["throws"], "details": "Jog 400m, then: A-skips 3 x 20y, bounds 3 x 15y, broad jumps 3 x 6, speed skaters 3 x 8 each, plyo push-ups 3 x 5, striders 3 x 40y. Every jump and bound is max effort with a full walk back. Class-choice days: the chosen class picks 3 movements x 2 rounds.", "workoutId": null, "attempts": null, "results": []}, {"kind": "drills", "title": "Shot drills", "minutes": 25, "groups": ["throws"], "details": "Glide: drivers x15, overhead throws x15, stand throws x6, step-back glides x4, full glides x4. Rotational: walking line throws x6, drop-in step-downs x6, dynamic wheel x4, South African x4. Coach one cue per athlete per day; film 2-3 stand throws for each athlete on video days.", "workoutId": null, "attempts": null, "results": []}, {"kind": "workout", "title": "Shot throws", "minutes": 20, "groups": ["throws"], "details": "Stand throws x8, full throws x8 at 85-90% effort. 30-40 total contacts with drills.", "workoutId": null, "attempts": null, "results": []}, {"kind": "strength", "title": "Lift A: lower-body power", "minutes": 40, "groups": ["throws"], "details": "1a Power clean + front squat 6 x 2/4. Weeks 1-2 at RPE 7, week 3 at RPE 8; add weight only when every rep is fast. Rest 2:00.\n2a DB Bulgarian split squat 4 x 6 each, 2b BB RDL 4 x 6 (RPE 7-8).\n3a Cossack squat 3 x 6 each, 3b landmine rotational press 3 x 6 each.", "workoutId": null, "attempts": null, "results": []}, {"kind": "cooldown", "title": "Mobility + core", "minutes": 15, "groups": ["throws"], "details": "Mobility: deep squat hold 2 x 1:00, 90/90 hip stretch 2 x 1:00 each, kneeling lunge hold 2 x 1:00 each, seated T-spine rotations 2 x 5 each, tib raises 2 x 25. Core: MB Russian twists 3 x 20, dead bugs 3 x 10, side plank 3 x 0:30 each.", "workoutId": null, "attempts": null, "results": []}]', 0, 'Cloverleaf throws 2026-27'),
  ('Throws M1: Discus technique + upper strength', 'General prep (March). Discus drills and Lift B. Alternate with the shot day so each implement gets 2-3 days a week.', '["throws"]', '[{"kind": "warmup", "title": "Throws warm-up", "minutes": 15, "groups": ["throws"], "details": "Jog 400m, then: A-skips 3 x 20y, bounds 3 x 15y, broad jumps 3 x 6, speed skaters 3 x 8 each, plyo push-ups 3 x 5, striders 3 x 40y. Every jump and bound is max effort with a full walk back. Class-choice days: the chosen class picks 3 movements x 2 rounds.", "workoutId": null, "attempts": null, "results": []}, {"kind": "drills", "title": "Discus drills", "minutes": 25, "groups": ["throws"], "details": "Pressers x20, front raises x20, stand throws x8, walking line throws x6, dynamic wheels x4, South African x6. Keep the release flat and the left side blocked; film 2-3 stand throws for each athlete on video days.", "workoutId": null, "attempts": null, "results": []}, {"kind": "workout", "title": "Discus throws", "minutes": 20, "groups": ["throws"], "details": "Stand throws x8, full throws x8 at 85-90% effort.", "workoutId": null, "attempts": null, "results": []}, {"kind": "strength", "title": "Lift B: upper-body strength", "minutes": 40, "groups": ["throws"], "details": "1a Bench press 5 x 5, building to one top set at RPE 8; 1b bent-over row 5 x 5.\n2a SA DB incline press 4 x 8 each, 2b pull-ups 4 x 6-8.\n3a DB reverse fly 3 x 12, 3b SA DB external rotation 3 x 10 each, farmer''s carry 3 x 30y.", "workoutId": null, "attempts": null, "results": []}, {"kind": "cooldown", "title": "Mobility + core", "minutes": 15, "groups": ["throws"], "details": "Mobility: wall slides 2 x 10, cross-body stretch 2 x 1:00, kneeling thoracic extension 2 x 10 each, cat-cow 2 x 10. Core: plank shoulder taps 3 x 10 each, V-ups 3 x 10, hollow body hold 3 x 0:30.", "workoutId": null, "attempts": null, "results": []}]', 0, 'Cloverleaf throws 2026-27'),
  ('Throws (any phase): Speed + plyo day', 'From the 2025-26 Day 14 speed session. Max-intent jumps, sprints, and med-ball throws with full rest, plus light technique. Once a week in every phase; halve it in championship weeks.', '["throws"]', '[{"kind": "warmup", "title": "Throws warm-up (short)", "minutes": 10, "groups": ["throws"], "details": "Jog 400m, A-skips 2 x 20y, lateral line hops 2 x 10 each, duck walks 2 x 10y, striders 2 x 40y.", "workoutId": null, "attempts": null, "results": []}, {"kind": "drills", "title": "Technique (light)", "minutes": 20, "groups": ["throws"], "details": "Shot: drivers x15, stand throws x6, step-back glides x4. Discus: pressers x15, stand throws x6, South African x4. Easy effort; this is rhythm work, not a throwing day.", "workoutId": null, "attempts": null, "results": []}, {"kind": "strength", "title": "Lift C: speed + plyos", "minutes": 30, "groups": ["throws"], "details": "Quality over volume; full rest; stop the set when height or distance drops.\nBox jumps 4 x 3, hurdle hops 4 x 5, broad jumps 4 x 3.\n10m accelerations x4, 30m fly sprints x4 (walk-back recovery).\nOverhead back med-ball throw 3 x 5, med-ball scoop throw 3 x 5 (boys 4 kg, girls 3 kg).", "workoutId": null, "attempts": null, "results": []}, {"kind": "cooldown", "title": "Mobility + core", "minutes": 15, "groups": ["throws"], "details": "Mobility: deep squat hold 2 x 1:00, 90/90 hip stretch 2 x 1:00 each, kneeling lunge hold 2 x 1:00 each, seated T-spine rotations 2 x 5 each, tib raises 2 x 25. Core: MB Russian twists 3 x 20, dead bugs 3 x 10, side plank 3 x 0:30 each.", "workoutId": null, "attempts": null, "results": []}]', 0, 'Cloverleaf throws 2026-27'),
  ('Throws (any phase): Hips, shoulders + med ball', 'Prehab and rotational power from the 2024-25 banded hip and shoulder days. Pair with a light technique session.', '["throws"]', '[{"kind": "warmup", "title": "Throws warm-up (short)", "minutes": 10, "groups": ["throws"], "details": "Jog 400m, A-skips 2 x 20y, lateral line hops 2 x 10 each, duck walks 2 x 10y, striders 2 x 40y.", "workoutId": null, "attempts": null, "results": []}, {"kind": "drills", "title": "Technique (light)", "minutes": 20, "groups": ["throws"], "details": "Either implement: stand throws x8 and one drill from the day''s cue list x10.", "workoutId": null, "attempts": null, "results": []}, {"kind": "strength", "title": "Lift D: hips, shoulders, med ball", "minutes": 30, "groups": ["throws"], "details": "Hips: lateral step squat 2 x 10 each, banded single-leg glute bridge 2 x 10 each, lateral band walks 2 x 15 each.\nShoulders: SA landmine press 3 x 10 each, incline DB Y-raise 3 x 10, bottoms-up KB walk 3 x 30 ft, SA DB internal/external rotation 2 x 10 each.\nRotational power: side med-ball throws 3 x 6 each, kneeling med-ball chest pass 3 x 8.", "workoutId": null, "attempts": null, "results": []}, {"kind": "cooldown", "title": "Mobility + core", "minutes": 15, "groups": ["throws"], "details": "Mobility: wall slides 2 x 10, cross-body stretch 2 x 1:00, kneeling thoracic extension 2 x 10 each, cat-cow 2 x 10. Core: plank shoulder taps 3 x 10 each, V-ups 3 x 10, hollow body hold 3 x 0:30.", "workoutId": null, "attempts": null, "results": []}]', 0, 'Cloverleaf throws 2026-27'),
  ('Throws M1: Deload day', 'Every third week of prep, and the week after the busiest meet stretch. Same movements, about 40% less volume; load stays the same.', '["throws"]', '[{"kind": "warmup", "title": "Throws warm-up (short)", "minutes": 10, "groups": ["throws"], "details": "Jog 400m, A-skips 2 x 20y, lateral line hops 2 x 10 each, duck walks 2 x 10y, striders 2 x 40y.", "workoutId": null, "attempts": null, "results": []}, {"kind": "drills", "title": "Drills", "minutes": 15, "groups": ["throws"], "details": "Half of the usual drill list (e.g. drivers x10, stand throws x5).", "workoutId": null, "attempts": null, "results": []}, {"kind": "workout", "title": "Throws", "minutes": 15, "groups": ["throws"], "details": "Full throws x6 at 85%. 20 total contacts.", "workoutId": null, "attempts": null, "results": []}, {"kind": "strength", "title": "Lift (reduced)", "minutes": 25, "groups": ["throws"], "details": "Main lift 3 sets instead of 5-6 at the same load (e.g. power clean + front squat 3 x 2/4, bench 3 x 5). One accessory pair at 2 sets.", "workoutId": null, "attempts": null, "results": []}, {"kind": "cooldown", "title": "Mobility + core", "minutes": 15, "groups": ["throws"], "details": "Mobility: deep squat hold 2 x 1:00, 90/90 hip stretch 2 x 1:00 each, kneeling lunge hold 2 x 1:00 each, seated T-spine rotations 2 x 5 each, tib raises 2 x 25. Core: MB Russian twists 3 x 20, dead bugs 3 x 10, side plank 3 x 0:30 each.", "workoutId": null, "attempts": null, "results": []}]', 0, 'Cloverleaf throws 2026-27'),
  ('Throws M2: Shot volume + Olympic lift', 'Late March to mid-April. More full throws, heavy/light implement contrast, power clean waves. From the 2024-25 M2 shot days.', '["throws"]', '[{"kind": "warmup", "title": "Throws warm-up", "minutes": 15, "groups": ["throws"], "details": "Jog 400m, then: A-skips 3 x 20y, bounds 3 x 15y, broad jumps 3 x 6, speed skaters 3 x 8 each, plyo push-ups 3 x 5, striders 3 x 40y. Every jump and bound is max effort with a full walk back. Class-choice days: the chosen class picks 3 movements x 2 rounds.", "workoutId": null, "attempts": null, "results": []}, {"kind": "drills", "title": "Shot drills", "minutes": 15, "groups": ["throws"], "details": "Drivers x10, stand throws x10, step-back throws x5.", "workoutId": null, "attempts": null, "results": []}, {"kind": "workout", "title": "Shot throws with implement contrast", "minutes": 25, "groups": ["throws"], "details": "3 heavy (boys 14 lb, girls 10 lb), 3 light (boys 10 lb, girls 3 kg), then 15 full throws with the competition shot. 30-35 throws total. Measure the best 3 of the last 5 once a week.", "workoutId": null, "attempts": null, "results": []}, {"kind": "strength", "title": "Olympic lift + squat", "minutes": 35, "groups": ["throws"], "details": "1a Power clean every minute on the minute: week 1 10 x 1, week 2 6 x 2, week 3 4 x 3 (RPE 8, bar speed fast).\n2a Back squat 4 x 4 (RPE 8), 2b box jumps 4 x 3.\n3a Plyo push-ups 3 x 5, 3b farmer''s carry 3 x 30y.", "workoutId": null, "attempts": null, "results": []}, {"kind": "cooldown", "title": "Mobility + core", "minutes": 15, "groups": ["throws"], "details": "Mobility: deep squat hold 2 x 1:00, 90/90 hip stretch 2 x 1:00 each, kneeling lunge hold 2 x 1:00 each, seated T-spine rotations 2 x 5 each, tib raises 2 x 25. Core: MB Russian twists 3 x 20, dead bugs 3 x 10, side plank 3 x 0:30 each.", "workoutId": null, "attempts": null, "results": []}]', 0, 'Cloverleaf throws 2026-27'),
  ('Throws M2: Discus volume + upper', 'Late March to mid-April. Discus full-throw volume with contrast and upper strength. From the 2024-25 M2 discus days.', '["throws"]', '[{"kind": "warmup", "title": "Throws warm-up", "minutes": 15, "groups": ["throws"], "details": "Jog 400m, then: A-skips 3 x 20y, bounds 3 x 15y, broad jumps 3 x 6, speed skaters 3 x 8 each, plyo push-ups 3 x 5, striders 3 x 40y. Every jump and bound is max effort with a full walk back. Class-choice days: the chosen class picks 3 movements x 2 rounds.", "workoutId": null, "attempts": null, "results": []}, {"kind": "drills", "title": "Discus drills", "minutes": 15, "groups": ["throws"], "details": "Pressers x15, front raises x15, stand throws x10, South African x6.", "workoutId": null, "attempts": null, "results": []}, {"kind": "workout", "title": "Discus throws with implement contrast", "minutes": 25, "groups": ["throws"], "details": "3 heavy, 3 light (if available), then 14-16 full throws with the competition discus. 30-35 throws total.", "workoutId": null, "attempts": null, "results": []}, {"kind": "strength", "title": "Upper strength", "minutes": 35, "groups": ["throws"], "details": "1a Bench press 4 x 5 (RPE 8), 1b SA DB row 4 x 8 each.\n2a Push press 4 x 3, 2b pull-ups 4 x 6.\n3a Landmine rotational press 3 x 6 each, 3b SA DB external rotation 2 x 10 each.", "workoutId": null, "attempts": null, "results": []}, {"kind": "cooldown", "title": "Mobility + core", "minutes": 15, "groups": ["throws"], "details": "Mobility: wall slides 2 x 10, cross-body stretch 2 x 1:00, kneeling thoracic extension 2 x 10 each, cat-cow 2 x 10. Core: plank shoulder taps 3 x 10 each, V-ups 3 x 10, hollow body hold 3 x 0:30.", "workoutId": null, "attempts": null, "results": []}]', 0, 'Cloverleaf throws 2026-27'),
  ('Throws M3: Heavy day (day after a meet)', 'Mid-April to early May: the main training day of a meet week (usually Wednesday). Highest throw volume and the only heavy lift. Low reps, high intent; no 12-15 rep sets in season.', '["throws"]', '[{"kind": "warmup", "title": "Throws warm-up", "minutes": 15, "groups": ["throws"], "details": "Jog 400m, then: A-skips 3 x 20y, bounds 3 x 15y, broad jumps 3 x 6, speed skaters 3 x 8 each, plyo push-ups 3 x 5, striders 3 x 40y. Every jump and bound is max effort with a full walk back. Class-choice days: the chosen class picks 3 movements x 2 rounds.", "workoutId": null, "attempts": null, "results": []}, {"kind": "drills", "title": "Fix-it drills", "minutes": 15, "groups": ["throws"], "details": "Two drills that target what broke down at the last meet (from video), x10 each.", "workoutId": null, "attempts": null, "results": []}, {"kind": "workout", "title": "Full throws", "minutes": 25, "groups": ["throws"], "details": "Stand throws x6, full throws x15-20 in both events, competition implements, 85-95% effort.", "workoutId": null, "attempts": null, "results": []}, {"kind": "strength", "title": "Heavy lift", "minutes": 35, "groups": ["throws"], "details": "1a Hang clean 4 x 3 (RPE 8), 1b box jumps 3 x 3.\n2a Back squat 3 x 4 or bench press 3 x 4 (alternate weeks, RPE 8).\n3a Pull-ups 3 x 6, 3b side med-ball throws 3 x 5 each.", "workoutId": null, "attempts": null, "results": []}, {"kind": "cooldown", "title": "Mobility + core", "minutes": 15, "groups": ["throws"], "details": "Mobility: deep squat hold 2 x 1:00, 90/90 hip stretch 2 x 1:00 each, kneeling lunge hold 2 x 1:00 each, seated T-spine rotations 2 x 5 each, tib raises 2 x 25. Core: MB Russian twists 3 x 20, dead bugs 3 x 10, side plank 3 x 0:30 each.", "workoutId": null, "attempts": null, "results": []}]', 0, 'Cloverleaf throws 2026-27'),
  ('Throws M3: Speed + technique', 'The day between the heavy day and a pre-meet day (usually Thursday). Fast, short, and technical.', '["throws"]', '[{"kind": "warmup", "title": "Throws warm-up", "minutes": 15, "groups": ["throws"], "details": "Jog 400m, then: A-skips 3 x 20y, bounds 3 x 15y, broad jumps 3 x 6, speed skaters 3 x 8 each, plyo push-ups 3 x 5, striders 3 x 40y. Every jump and bound is max effort with a full walk back. Class-choice days: the chosen class picks 3 movements x 2 rounds.", "workoutId": null, "attempts": null, "results": []}, {"kind": "drills", "title": "Technique", "minutes": 20, "groups": ["throws"], "details": "Stand throws x6 and full throws x6 per event at 90%. Film each athlete''s best throw.", "workoutId": null, "attempts": null, "results": []}, {"kind": "strength", "title": "Speed + plyo (half)", "minutes": 20, "groups": ["throws"], "details": "Box jumps 3 x 3, hurdle hops 3 x 4, 10m accelerations x3, overhead back med-ball throw 2 x 5.", "workoutId": null, "attempts": null, "results": []}, {"kind": "other", "title": "Video review", "minutes": 15, "groups": ["throws"], "details": "Each athlete watches their clip with a coach and picks one cue for the next meet.", "workoutId": null, "attempts": null, "results": []}, {"kind": "cooldown", "title": "Mobility + core", "minutes": 15, "groups": ["throws"], "details": "Mobility: wall slides 2 x 10, cross-body stretch 2 x 1:00, kneeling thoracic extension 2 x 10 each, cat-cow 2 x 10. Core: plank shoulder taps 3 x 10 each, V-ups 3 x 10, hollow body hold 3 x 0:30.", "workoutId": null, "attempts": null, "results": []}]', 0, 'Cloverleaf throws 2026-27'),
  ('Throws (any phase): Pre-meet day', 'The day before every meet, as in all three past seasons: short, sharp, and confident.', '["throws"]', '[{"kind": "warmup", "title": "Throws warm-up (short)", "minutes": 10, "groups": ["throws"], "details": "Jog 400m, A-skips 2 x 20y, lateral line hops 2 x 10 each, duck walks 2 x 10y, striders 2 x 40y.", "workoutId": null, "attempts": null, "results": []}, {"kind": "workout", "title": "Competition rehearsal", "minutes": 20, "groups": ["throws"], "details": "Competition warm-up x3-5, then competition throws x4-6 in each event at full effort with the meet routine (name called, set, throw).", "workoutId": null, "attempts": null, "results": []}, {"kind": "strength", "title": "Activation", "minutes": 10, "groups": ["throws"], "details": "Broad jumps 2 x 2, med-ball scoop throw 2 x 3. Nothing to fatigue.", "workoutId": null, "attempts": null, "results": []}, {"kind": "cooldown", "title": "Mobility", "minutes": 10, "groups": ["throws"], "details": "Deep squat hold 2 x 1:00, pigeon stretch 1:00 each, shoulder pass-throughs 2 x 10.", "workoutId": null, "attempts": null, "results": []}]', 0, 'Cloverleaf throws 2026-27'),
  ('Throws M4: Championship sharpen', 'League through State (mid-May to June). The weeks the old calendars left blank. Throw count drops; intensity stays high. Last hard session 4-5 days before each championship meet.', '["throws"]', '[{"kind": "warmup", "title": "Throws warm-up", "minutes": 15, "groups": ["throws"], "details": "Jog 400m, then: A-skips 3 x 20y, bounds 3 x 15y, broad jumps 3 x 6, speed skaters 3 x 8 each, plyo push-ups 3 x 5, striders 3 x 40y. Every jump and bound is max effort with a full walk back. Class-choice days: the chosen class picks 3 movements x 2 rounds.", "workoutId": null, "attempts": null, "results": []}, {"kind": "workout", "title": "Quality throws", "minutes": 20, "groups": ["throws"], "details": "Stand throws x3 and full throws x6-8 per event at 95-100%, full rest between throws. Stop on a good one; 10-15 throws total.", "workoutId": null, "attempts": null, "results": []}, {"kind": "strength", "title": "Speed lifts", "minutes": 25, "groups": ["throws"], "details": "Hang clean 3 x 2 at RPE 7 (fast), squat or bench 3 x 3 at RPE 7 (fast bar), box jumps 2 x 3. About half the April volume. Skip entirely within 3 days of a championship meet.", "workoutId": null, "attempts": null, "results": []}, {"kind": "cooldown", "title": "Mobility", "minutes": 10, "groups": ["throws"], "details": "Standing pigeon 2 x 1:00, goblet duck walk 2 x 1:00, panther crawls 2 x 1:00.", "workoutId": null, "attempts": null, "results": []}]', 0, 'Cloverleaf throws 2026-27'),
  ('Throws (any phase): Recovery + class choice', 'End-of-week recovery from the 2024-25 Friday days: yoga, mobility, light drills, and a class-choice warm-up.', '["throws"]', '[{"kind": "warmup", "title": "Class-choice warm-up", "minutes": 10, "groups": ["throws"], "details": "The chosen class picks 3-4 movements x 2 rounds from the warm-up list.", "workoutId": null, "attempts": null, "results": []}, {"kind": "drills", "title": "Light drills", "minutes": 15, "groups": ["throws"], "details": "Drivers x10 and stand throws x5 per event at 70%.", "workoutId": null, "attempts": null, "results": []}, {"kind": "other", "title": "Yoga + mobility", "minutes": 25, "groups": ["throws"], "details": "Yoga flow or the full mobility list; ice baths if available.", "workoutId": null, "attempts": null, "results": []}, {"kind": "cooldown", "title": "Core", "minutes": 10, "groups": ["throws"], "details": "Dead bugs 3 x 10, front plank 3 x 1:00, glute bridge 3 x 15.", "workoutId": null, "attempts": null, "results": []}]', 0, 'Cloverleaf throws 2026-27'),
  ('Throws (any phase): Throw-a-thon / mock meet', 'Competition simulation from the past seasons'' mock meet and throw-a-thon. Three attempts plus three finals, measured and recorded.', '["throws"]', '[{"kind": "warmup", "title": "Throws warm-up", "minutes": 15, "groups": ["throws"], "details": "Jog 400m, then: A-skips 3 x 20y, bounds 3 x 15y, broad jumps 3 x 6, speed skaters 3 x 8 each, plyo push-ups 3 x 5, striders 3 x 40y. Every jump and bound is max effort with a full walk back. Class-choice days: the chosen class picks 3 movements x 2 rounds.", "workoutId": null, "attempts": null, "results": []}, {"kind": "measured", "title": "Shot put flight", "minutes": 25, "groups": ["throws"], "details": "Competition warm-up x3, then 3 attempts; top half gets 3 finals. Record every mark.", "workoutId": null, "attempts": 6, "results": []}, {"kind": "measured", "title": "Discus flight", "minutes": 25, "groups": ["throws"], "details": "Competition warm-up x3, then 3 attempts; top half gets 3 finals. Record every mark.", "workoutId": null, "attempts": 6, "results": []}, {"kind": "cooldown", "title": "Mobility", "minutes": 10, "groups": ["throws"], "details": "Deep squat hold 2 x 1:00, pigeon stretch 1:00 each, cat-cow 2 x 10.", "workoutId": null, "attempts": null, "results": []}]', 0, 'Cloverleaf throws 2026-27');
